@startuml

class Cinema {
  + Town : string
}

class Theatre {
  + NumberOfSeats : int
}

class Movie {
  + Name : string
}

class MovieCopy {
  + CopyId : string
}

class Show {
  + StartTime : datetime
  + IsPublished : boolean
}

class Reservation {
  + ReservationTime : datetime
  + IsCancelled : boolean
}

class CreditCard {
  + CardNumber : string
}

class Ticket {
  + SeatNumber : string
  + IsAnonymous : boolean
}

class Offer {
  + ExpiryTime : datetime
  + Status : string
}

class Customer {
  + Name : string
}

Cinema "1" -- "0..*" Theatre
Cinema "1" -- "0..*" MovieCopy
Theatre "1" -- "0..*" Show
Movie "1" -- "0..*" MovieCopy
MovieCopy "1" -- "0..*" Show
Show "1" -- "0..*" Reservation
Show "1" -- "0..*" Ticket
Show "1" -- "0..*" Offer
Customer "1" -- "0..*" Reservation
Customer "0..1" -- "0..*" Offer
Reservation "1" -- "1" CreditCard
Reservation "1" -- "1" Ticket
Ticket "0..*" -- "1" MovieCopy

@enduml

